-- 120: Original BrillaPrep WASSCE Commerce Detailed Syllabus beta questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_001', 'topic_was_commerce_1', 'subj_wassce_commerce', 'exam_wassce', 'Which statement best describes commerce?', 'multiple_choice', '["A. Activities that facilitate the exchange and distribution of goods and services","B. Only the extraction of raw materials","C. Only manufacturing goods in factories","D. Any activity performed without exchange"]', 'A', 'Commerce connects producers and consumers through trade and the services that support trade, including transport, banking, insurance, warehousing and communication. Therefore the correct answer is A: Activities that facilitate the exchange and distribution of goods and services.', 'easy', 1, 1, 90, 'st_was_commerce_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_002', 'topic_was_commerce_1', 'subj_wassce_commerce', 'exam_wassce', 'Which factor of production receives rent as its usual reward?', 'multiple_choice', '["A. Labour","B. Land","C. Capital","D. Entrepreneurship"]', 'B', 'Land includes natural resources used in production, and its payment is rent. Labour earns wages, capital earns interest, and entrepreneurship earns profit. Therefore the correct answer is B: Land.', 'medium', 2, 2, 90, 'st_was_commerce_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_003', 'topic_was_commerce_1', 'subj_wassce_commerce', 'exam_wassce', 'A cocoa farmer, a chocolate factory worker and a retailer belong respectively to which occupational groups?', 'multiple_choice', '["A. Secondary, primary and direct service","B. Commercial, primary and secondary","C. Primary, secondary and commercial","D. Direct service, commercial and primary"]', 'C', 'The farmer extracts a natural product, the factory transforms it, and the retailer helps distribute the finished product to consumers. Therefore the correct answer is C: Primary, secondary and commercial.', 'hard', 1, 1, 90, 'st_was_commerce_1', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_004', 'topic_was_commerce_1', 'subj_wassce_commerce', 'exam_wassce', 'What is a likely advantage of division of labour in a factory?', 'multiple_choice', '["A. Every worker must master every production stage","B. Production becomes independent of coordination","C. Repetition can never affect worker motivation","D. Workers can specialise and increase output"]', 'D', 'Specialisation can improve speed and skill through repeated performance of a limited task, although excessive repetition can also create monotony. Therefore the correct answer is D: Workers can specialise and increase output.', 'easy', 2, 2, 90, 'st_was_commerce_1', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_005', 'topic_was_commerce_1', 'subj_wassce_commerce', 'exam_wassce', 'Why is an entrepreneur important in production?', 'multiple_choice', '["A. The entrepreneur organises resources and bears business risk","B. The entrepreneur supplies only unskilled labour","C. The entrepreneur fixes all market prices","D. The entrepreneur removes the need for capital"]', 'A', 'Entrepreneurs combine land, labour and capital, make decisions, innovate and accept the possibility that business outcomes may differ from plans. Therefore the correct answer is A: The entrepreneur organises resources and bears business risk.', 'medium', 3, 3, 90, 'st_was_commerce_1', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_006', 'topic_was_commerce_2', 'subj_wassce_commerce', 'exam_wassce', 'Which feature most clearly distinguishes a sole proprietorship?', 'multiple_choice', '["A. Its shares must be sold on a stock exchange","B. One person owns and controls the business","C. It must have at least twenty partners","D. Government owns all of its assets"]', 'B', 'A sole proprietorship is owned by one individual who normally controls decisions and receives profit while bearing unlimited liability. Therefore the correct answer is B: One person owns and controls the business.', 'hard', 2, 2, 90, 'st_was_commerce_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_007', 'topic_was_commerce_2', 'subj_wassce_commerce', 'exam_wassce', 'What is the main purpose of a partnership deed?', 'multiple_choice', '["A. To advertise products to the public","B. To replace every law governing partnerships","C. To record partners’ rights, duties and agreed business terms","D. To guarantee that the partnership cannot dissolve"]', 'C', 'A partnership deed reduces uncertainty by documenting capital contributions, profit sharing, responsibilities, admission, retirement and dispute procedures. Therefore the correct answer is C: To record partners’ rights, duties and agreed business terms.', 'easy', 1, 1, 90, 'st_was_commerce_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_008', 'topic_was_commerce_2', 'subj_wassce_commerce', 'exam_wassce', 'What does limited liability protect a shareholder from?', 'multiple_choice', '["A. A fall in the market value of shares","B. Every consequence of fraudulent conduct","C. The company making a trading loss","D. Losing more than the amount committed to the company"]', 'D', 'A company is legally separate from its shareholders, so an ordinary shareholder’s financial exposure is generally limited to the unpaid amount on the shares. Therefore the correct answer is D: Losing more than the amount committed to the company.', 'medium', 2, 2, 90, 'st_was_commerce_2', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_009', 'topic_was_commerce_2', 'subj_wassce_commerce', 'exam_wassce', 'Which principle is central to a co-operative society?', 'multiple_choice', '["A. Members jointly own it to advance shared economic interests","B. Voting power always depends only on wealth","C. Profit for outside investors is its sole purpose","D. Membership must be restricted to government officials"]', 'A', 'Co-operatives are formed by members who pool resources and use democratic structures to obtain services or market benefits for the membership. Therefore the correct answer is A: Members jointly own it to advance shared economic interests.', 'hard', 1, 1, 90, 'st_was_commerce_2', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_010', 'topic_was_commerce_2', 'subj_wassce_commerce', 'exam_wassce', 'Why might a public enterprise be established?', 'multiple_choice', '["A. To prevent government from delivering infrastructure","B. To provide an essential service with significant public interest","C. To ensure that all services maximise short-term profit","D. To eliminate public accountability"]', 'B', 'Public enterprises may provide strategic or essential services where access, long-term investment or national policy matters alongside financial performance. Therefore the correct answer is B: To provide an essential service with significant public interest.', 'easy', 3, 3, 90, 'st_was_commerce_2', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published WAEC Ghana Commerce syllabus; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2024/07/COMMERCE.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_commerce_b001_001' AND 'q_was_commerce_b001_010';
